INSERT INTO knowledge_chunk (doc, title, tags, body, sort_order) VALUES
  ('01-detection-basics', 'AI 检测是怎么判断的', '检测原理,AI率,校准,置信区间,怎么判', '平台把论文按段落切开，每段送进一个在大量「人写 / AI 写」中文语料上微调过的语言模型（DeBERTa 系 encoder），模型输出这段是 AI 生成的概率。整篇的 AI 率是各正文段落概率的加权平均，参考文献、致谢、标题等非正文段落会被排除，不参与计算。

判断依据不是「有没有某个关键词」，而是文本的整体统计特征：句子长短的节奏、用词的丰富程度、连接词的使用习惯、标点的分布等。AI 生成的文本在这些维度上往往比人写的「更匀、更规整」。', 0),
  ('01-detection-basics', '什么是校准概率，为什么和原始概率不一样', '检测原理,AI率,校准,置信区间,怎么判', '模型直接吐出的数字叫原始概率，往往过于自信（一段文本给 0.95，实际上十段里只有七段真是 AI）。校准就是在验证集上学一个修正函数（温度缩放 + Platt），把原始概率拉回到「说 0.7 就大概真有 70% 是 AI」的水平。报告里展示和用来比红线的，都是校准后的概率。', 1),
  ('01-detection-basics', '置信区间是什么意思', '检测原理,AI率,校准,置信区间,怎么判', '每个概率旁边的区间表示「模型自己对这个数有多不确定」。区间宽说明证据不足（比如段落太短、文体特殊），窄说明判断比较稳。看到区间跨过红线（比如 15%-25%，红线 20%），说明这一段是边界情况，不该单凭这个数下结论。', 2),
  ('01-detection-basics', '为什么段落太短不可靠', '检测原理,AI率,校准,置信区间,怎么判', '统计特征需要足够的文本量才稳定。文献和实测都表明约 120 字以下，检测器的判断能力明显下降。报告里对短段落会标 warning，助手也会提醒。如果整篇都是短段落（比如 PPT 式提纲），建议合并后再测。', 3),
  ('01-detection-basics', '什么是红黄绿', '检测原理,AI率,校准,置信区间,怎么判', '按校准概率分三档：低于 0.4 绿（低风险）、0.4 到 0.7 黄（中风险）、0.7 以上红（高风险）。红黄绿是段落级的提示，帮你快速定位该优先看哪几段；整体是否「过线」看的是整篇 AI 率和场景红线的比较，不是红段数量。', 4),
  ('01-detection-basics', '为什么同一段话两次检测结果不完全一样', '检测原理,AI率,校准,置信区间,怎么判', '模型本身是确定的，同一段文字结果一致。差异通常来自：① 分段边界变了（多了或少了几个字，段落被切到不同位置）；② 模型版本升级；③ 复制时带进了不可见字符或格式。如果差异很大，可以把两次的段落对照看一下。', 5),
  ('01-detection-basics', '检测结果会不会误判', '检测原理,AI率,校准,置信区间,怎么判', '会。任何检测器都有误判，尤其对高度规范化的学术写作（见「为什么学术写作容易被误判」）。所以平台提供人工复核和申诉通道，检测结果是辅助信号，不是终审判决。', 6),
  ('02-why-academic-misjudged', '学术文体天然和 AI 文本重叠', '误判,学术写作,假阳性,非母语,文体', '学术摘要和技术报告追求清晰、一致、结构规整、少情绪，这些恰恰也是 AI 生成文本的统计特点。研究（Chen 2026 的错误分析）直接指出：被误判为 AI 的人类文本，共同特征是「高度标准化的格式、低情绪波动、风格不规则性少」。换句话说，写得越「标准」，越容易被当成 AI。这是检测任务本身的内生难点，不是你写得有问题。', 7),
  ('02-why-academic-misjudged', '非母语和「被润色过」的文本更容易被误判', '误判,学术写作,假阳性,非母语,文体', '一项覆盖 13.5 万篇稿件的研究（Style as a Confound, 2026）发现：同一篇非母语作者的学术稿，经专业编辑润色后，不同检测器给出的 AI 分数变化方向都不一致，假阳率从 0% 到 100% 不等。「专业编辑风格」本身就是一个强干扰因素。中文论文里对应的情况是：经过导师、同学反复修改、语句被打磨得很规整的稿子，AI 分数可能偏高。', 8),
  ('02-why-academic-misjudged', '微调检测器的结构性偏差', '误判,学术写作,假阳性,非母语,文体', '2026 年的一项分析（Amplifying, Not Learning）认为，微调出来的检测器并没有学到真正的「AI vs 人」边界，而是放大了预训练语言模型里已有的「文本可预测性」这根轴。可预测性高的正式文本——无论谁写的——都会被推向 AI 一侧。这个偏差无法靠调阈值或集成完全消除，所以平台把结果定位为「疑似标记 + 人工复核」。', 9),
  ('02-why-academic-misjudged', '这对你意味着什么', '误判,学术写作,假阳性,非母语,文体', '如果你的论文被判超标，但你确定是自己写的：先看报告里风险最高的几段，它们是不是恰好写得特别「教科书」；再看区间是否跨线；然后通过申诉提交人工复核，附上写作过程材料。平台不会单凭一个数字下结论。', 10),
  ('02-why-academic-misjudged', '哪些写作习惯在统计上更像人写的', '误判,学术写作,假阳性,非母语,文体', '人类写作通常有这些特点：长短句交错而不是每句差不多长；会用具体的例子、数据、个人经验而不是泛泛而谈；连接词用得少而自然，不是每段都「首先…其次…综上所述」；偶尔有不那么「标准」的表达。这些不是让你去「模仿人类」，而是提醒：写作时放进自己的具体思考和材料，文本自然就不会那么「匀」。', 11),
  ('03-policy-thresholds', '教育部指导意见与默认红线', '红线,阈值,政策,教育部,本科,硕士,博士,能过吗', '教育部 2025 年发布《关于加强高等学校学位论文 AIGC 检测工作的指导意见》，2026 年春季学期起全国高校全面实施。平台默认红线按学位类型配置：本科论文 AI 率不超过 20%，硕士不超过 15%，博士不超过 10%。职业报告类默认 15%，自媒体类 30%，其他场景 25%。这些是平台默认值，运营可以按最新文件调整，助手回答时会取当前生效值。', 12),
  ('03-policy-thresholds', '各高校可能更严格', '红线,阈值,政策,教育部,本科,硕士,博士,能过吗', '一些学校有自己的内部规定，例如：清华大学不超过 20%；北京大学硕博检测结果作为答辩参考材料；中国人民大学 AIGC 超过 30% 不予通过。具体以你所在学校研究生院/教务处的最新通知为准，学院也可能有更细的要求。平台的红线只是参考线，不替代学校的判定。', 13),
  ('03-policy-thresholds', '红线比较的是什么数', '红线,阈值,政策,教育部,本科,硕士,博士,能过吗', '比较的是整篇论文校准后的整体 AI 率，不是某一段的概率，也不是红段的数量。整体 AI 率是正文段落按字数加权的平均。参考文献、致谢、目录、标题等非正文内容不参与计算。', 14),
  ('03-policy-thresholds', '边界情况怎么看', '红线,阈值,政策,教育部,本科,硕士,博士,能过吗', '如果整体 AI 率和红线很接近（比如 18% 对 20%），或者置信区间跨过红线，这属于边界情况。建议：① 看风险最高的几段是否确实有问题；② 保留写作过程材料；③ 如果确定是自己写的，提交人工复核。不要因为一个边界数字就大幅改动已经写好的内容。', 15),
  ('03-policy-thresholds', '检测报告能不能当答辩材料', '红线,阈值,政策,教育部,本科,硕士,博士,能过吗', '部分学校接受平台检测报告作为答辩参考材料之一。报告里包含整体 AI 率、场景与红线、置信区间、模型版本和检测时间，可以导出 PDF。但报告是否被学校认可、是否需要用学校指定的检测系统，要以学校规定为准。', 16),
  ('04-defense-materials', '答辩前建议准备哪些材料', '答辩,材料,准备,过程稿,导师,证明', '除学校要求的论文定稿和检测报告外，建议准备能证明写作过程的材料：① 各阶段的草稿或版本记录（Word 的版本历史、Git、网盘的历史版本都算）；② 文献管理软件里的阅读与笔记记录；③ 与导师的沟通记录（邮件、聊天、批注稿）；④ 实验数据、调研原始记录、代码仓库等一手材料。这些材料在被问到「论文是否 AI 生成」时最有说服力。', 17),
  ('04-defense-materials', '检测报告里哪些信息对答辩有用', '答辩,材料,准备,过程稿,导师,证明', '整体 AI 率与对应场景的红线；风险最高段落的位置和概率（方便你提前准备解释）；置信区间（说明边界情况）；模型版本与检测时间（证明检测时效）。导出 PDF 时这些都在。', 18),
  ('04-defense-materials', '如果被问「这段是不是 AI 写的」怎么回答', '答辩,材料,准备,过程稿,导师,证明', '先说明这段的内容来源（哪篇文献、哪组数据、哪次讨论），再说明为什么会这么写（学科惯例、导师要求、期刊格式）。能拿出过程材料的直接展示。不要去争论检测器准不准，重点是证明你的写作过程。', 19),
  ('04-defense-materials', '用 AI 工具辅助过写作该怎么说明', '答辩,材料,准备,过程稿,导师,证明', '如果使用了 AI 工具做文献检索、语法检查、格式整理等辅助工作，按学校规定如实说明使用范围。多数学校允许辅助性使用但要求披露；完全由 AI 生成核心内容则不被允许。具体口径看学校的学术诚信规定。', 20),
  ('04-defense-materials', '检测没过怎么办', '答辩,材料,准备,过程稿,导师,证明', '先别慌。① 看报告，找到贡献最大的几段；② 判断这几段是不是自己写的——如果是，走申诉/人工复核；③ 如果确实有 AI 生成的内容，按学校规定处理，通常是自己重写相关部分；④ 和导师沟通，导师的意见在这类事情上很重要。', 21),
  ('05-academic-norms', 'AIGC 检测和查重是两回事', '学术规范,引用,查重,学术诚信,格式', '查重（如知网查重）比的是你的文字和已有文献的重复程度；AIGC 检测判断的是文字是不是 AI 生成的。一段完全原创、从没人写过的文字，查重为 0，但如果是 AI 写的，AIGC 检测会标出来。反过来，一段大量引用但由你自己组织的文字，查重可能偏高，但 AIGC 率可以很低。两者要分别过。', 22),
  ('05-academic-norms', '引用规范的基本要求', '学术规范,引用,查重,学术诚信,格式', '直接引用要加引号并标注出处；转述他人观点也要标注；数据、图表、代码要注明来源；参考文献格式按学校或期刊要求（GB/T 7714、APA 等）统一。规范引用不会提高 AIGC 率——参考文献段落本身不参与计算。', 23),
  ('05-academic-norms', '什么算学术不端', '学术规范,引用,查重,学术诚信,格式', '常见类型：抄袭、剽窃、伪造或篡改数据、不当署名、一稿多投、由他人（包括 AI）代写核心内容。各校学术诚信规定有详细定义和处理办法，涉及这类问题时，以学校规定为准，不要听信「怎么绕过检测」之类的建议。', 24),
  ('05-academic-norms', '使用 AI 工具的合理边界', '学术规范,引用,查重,学术诚信,格式', '多数高校当前的口径是：允许用 AI 做文献检索、语法与格式检查、思路讨论等辅助工作，但核心内容（研究问题、方法、分析、结论）必须由作者本人完成，且使用情况需按要求披露。具体以学校规定为准。', 25),
  ('05-academic-norms', '导师的角色', '学术规范,引用,查重,学术诚信,格式', '导师对论文的学术质量和诚信负有指导责任。遇到检测结果争议、不确定某种 AI 使用方式是否合规，优先和导师沟通，导师的意见和学院的规定是最终依据。', 26),
  ('06-appeal-flow', '什么情况适合申诉', '申诉,复核,误判,反馈,流程', '你确定被标红的段落是自己写的；或者整体 AI 率在红线附近、置信区间跨线；或者报告里的判定和你的写作过程材料明显矛盾。申诉不是「不服就申诉」，而是提供证据请人工复核。', 27),
  ('06-appeal-flow', '怎么提交申诉', '申诉,复核,误判,反馈,流程', '两种方式：① 在报告页点「申诉」，填写理由；② 直接告诉助手「我想申诉」，说明理由，助手复述确认后帮你提交。申诉会关联到具体的检测任务，理由里最好写清：哪几段、为什么认为是误判、有什么过程材料可以提供。', 28),
  ('06-appeal-flow', '提交后会发生什么', '申诉,复核,误判,反馈,流程', '申诉进入运营的人工复核队列，状态从「待处理」变为「处理中」再到「已回复」。复核人员会结合段落内容、表层特征证据和你提供的材料给出结论。结论和回复在「我的反馈」里查看，如果有订阅通知也会推送。', 29),
  ('06-appeal-flow', '复核结论有哪些', '申诉,复核,误判,反馈,流程', '通常是三种之一：维持原判定（并说明依据）；调整判定（标注误判段落，整体 AI 率相应修正）；需要补充材料（请你提供更多过程证据）。调整后的结果会更新到原报告。', 30),
  ('06-appeal-flow', '申诉不是万能的', '申诉,复核,误判,反馈,流程', '人工复核能纠正明显误判，但不能把确实由 AI 生成的内容「洗白」。如果复核维持原判定，建议和导师沟通后按学校规定处理。', 31),
  ('07-verification', '为什么拿到报告要先「核验」而不是直接改', '核验,复核,误判,自查,过程材料,申诉', '平台的检测结果定位是「疑似标记 + 人工复核」，不是终审判决。任何检测器都会误判——独立测试里国际主流产品的准确率也只有八成多、每十篇里就有一两篇假阳，而高度规范化的学术写作又是最容易中招的那类。所以正确的第一反应不是「我的论文有问题，赶紧改」，而是先花几分钟核验：这几段到底是不是我自己写的。数字是参考信号，你的写作过程才是真相。', 32),
  ('07-verification', '自查三步：拿到报告先看什么', '核验,复核,误判,自查,过程材料,申诉', '① 找风险最高的几段（红色、概率高的），逐段回忆：这些内容是不是我写的？有没有参考过 AI 的输出？② 看置信区间：区间跨过红线、或者整体 AI 率贴着红线，说明是边界情况，单凭一个数不该下结论。③ 看溯源标签：报告里标注的「疑似来源」跟你实际用过的工具对得上吗？对不上往往提示误判。三步走完，你对这份报告就有数了，再决定是申诉还是修改。', 33),
  ('07-verification', '哪些情况更像是误判', '核验,复核,误判,自查,过程材料,申诉', '这几类文本在统计上天然容易被判成 AI：写得特别「教科书」的正规学术体、非母语写作者、用过润色工具改过的文字、特别短的段落（约 120 字以下）。如果你被标红的段落恰好落在这些类型里，误判的可能性就更高，更值得走核验。反过来，如果你确实大段参考了 AI 输出，那大概率不是误判，老老实实重写更省事。', 34),
  ('07-verification', '写作过程材料是核验的关键证据', '核验,复核,误判,自查,过程材料,申诉', '人工复核最怕「空口说是我写的」。能证明你写作过程的材料越多，核验越有说服力：带时间戳的草稿和修订记录、实验数据、文献笔记、和导师讨论的聊天记录、甚至 git 提交历史。所以平时写作就建议保留过程痕迹，别只留最终稿。申诉时把这些材料一起提交，比一句「我真的是自己写的」有用得多。', 35),
  ('07-verification', '平台怎么核验：人工复核流程', '核验,复核,误判,自查,过程材料,申诉', '你提交申诉后，会进入运营的人工复核队列，状态从「待处理」到「处理中」再到「已回复」。复核人员会结合三样东西看：段落原文、模型给出的表层特征证据（句长节奏、用词丰富度、套话连接词等）、以及你提供的材料。结论通常在「我的反馈」里查看。注意：运营复核是「看证据做判断」，不会只凭一个数字拍板。', 36),
  ('07-verification', '核验的边界与结论', '核验,复核,误判,自查,过程材料,申诉', '复核能纠正明显误判，但不能把确实由 AI 生成的内容「洗白」；平台也不会在后台直接改你的报告结论，而是通过「维持原判定 / 调整判定 / 请你补充材料」三种结论来回应。被认定为合理误判的申诉会记入模型改进清单，用来优化下一版检测器。核验不是为了推翻一切，而是让结论更接近事实。', 37),
  ('07-verification', '核验之后怎么做', '核验,复核,误判,自查,过程材料,申诉', '如果复核维持判定，说明这几段大概率确实接近 AI 文风——和导师沟通后，按学校规定用自己的话重写相关内容即可。如果判定被调整，用更新后的报告结论。无论哪种结果，写作过程材料都建议继续留着：它既是答辩时的底气，也是将来再次核验时的证据。', 38)
ON DUPLICATE KEY UPDATE
  tags       = VALUES(tags),
  body       = VALUES(body),
  sort_order = VALUES(sort_order),
  enabled    = 1;
